-- Menu & recipes (Oct 2026). Safe to run more than once.
-- One row per dish or drink: what guests see (name, price, description, photo)
-- plus what staff need (ingredients with amounts, steps, notes). Kitchen and bar
-- staff can read it; managers edit it in the dashboard.

create table if not exists menu_items (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  section text not null,
  menu text not null default 'mornings' check (menu in ('mornings', 'all_day', 'nights', 'drinks')),
  station text not null default 'kitchen' check (station in ('kitchen', 'bar')),
  price numeric(8,2),
  description text,
  photo_url text,
  ingredients jsonb not null default '[]'::jsonb, -- [{ name, qty, unit, item_id? }]
  steps text,
  notes text,
  allergens text,
  sort int not null default 0,
  active boolean not null default true,
  updated_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists menu_items_sort_idx on menu_items (sort);

alter table menu_items enable row level security;
revoke all on menu_items from anon, authenticated;

-- Photos: public bucket (dish photos aren't private); uploads go through the dashboard server
on conflict (id) do nothing;

-- The current menus, only on the first run (Oct 15 2026: printed Mornings + Nights menus and the website)
do $$
begin
  if exists (select 1 from menu_items) then
    return;
  end if;

end $$;

notify pgrst, 'reload schema';
